#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/core_names.h>
#include <openssl/params.h>

static EVP_MAC *g_mac = NULL;
static EVP_CIPHER *g_ciph = NULL;

typedef struct {
    const unsigned char *key; const unsigned char *nonce;
    const unsigned char *pt; unsigned char *ct;
    size_t off, len;            /* byte offset into pt, len (off multiple of 64) */
    unsigned char rkey[32];
    unsigned char t1[16], t2[16];
    int err;
} job_t;

#define SUB 16384
static void *worker(void *arg) {
    job_t *j = (job_t*)arg;
    j->err = 1;
    EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
    unsigned char iv[16];
    uint32_t ctr = (uint32_t)(1 + j->off / 64);
    iv[0]=ctr; iv[1]=ctr>>8; iv[2]=ctr>>16; iv[3]=ctr>>24;
    memcpy(iv+4, j->nonce, 12);
    if (!EVP_EncryptInit_ex(c, g_ciph, NULL, j->key, iv)) return NULL;
    EVP_MAC_CTX *m = EVP_MAC_CTX_new(g_mac);
    if (!EVP_MAC_init(m, j->rkey, 32, NULL)) return NULL;
    size_t pos = 0; int outl;
    size_t full = j->len & ~(size_t)15;
    while (pos < j->len) {
        size_t n = j->len - pos; if (n > SUB) n = SUB;
        EVP_EncryptUpdate(c, j->ct + j->off + pos, &outl, j->pt + j->off + pos, (int)n);
        size_t mn = n;
        if (pos + n > full) mn = full - pos;
        if (mn) EVP_MAC_update(m, j->ct + j->off + pos, mn);
        pos += n;
    }
    if (full < j->len) {
        unsigned char blk[16] = {0};
        memcpy(blk, j->ct + j->off + full, j->len - full);
        EVP_MAC_update(m, blk, 16);
    }
    EVP_MAC_CTX *m2 = EVP_MAC_CTX_dup(m);
    unsigned char z[16] = {0};
    EVP_MAC_update(m2, z, 16);
    size_t ol;
    EVP_MAC_final(m, j->t1, &ol, 16);
    EVP_MAC_final(m2, j->t2, &ol, 16);
    EVP_MAC_CTX_free(m); EVP_MAC_CTX_free(m2); EVP_CIPHER_CTX_free(c);
    j->err = 0;
    return NULL;
}

#define MAXT 64
/* enc(key, nonce, plaintext, rkey, nthreads) -> (ct_bytes, [(t1,t2,len),...]) */
static PyObject *enc(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, rk; int nt;
    if (!PyArg_ParseTuple(args, "y*y*y*y*i", &key, &nonce, &pt, &rk, &nt)) return NULL;
    size_t L = pt.len;
    PyObject *out = PyBytes_FromStringAndSize(NULL, L);
    unsigned char *ct = (unsigned char*)PyBytes_AS_STRING(out);
    if (nt > MAXT) nt = MAXT;
    size_t per = (L / nt + 63) & ~(size_t)63;
    if (per < 65536) per = 65536;
    job_t jobs[MAXT]; pthread_t th[MAXT]; int cnt = 0;
    for (size_t o = 0; o < L && cnt < MAXT; o += per) {
        job_t *j = &jobs[cnt];
        j->key = key.buf; j->nonce = nonce.buf; j->pt = pt.buf; j->ct = ct;
        j->off = o; j->len = (L - o < per) ? L - o : per;
        memcpy(j->rkey, rk.buf, 16); memset(j->rkey+16, 0, 16);
        cnt++;
    }
    Py_BEGIN_ALLOW_THREADS
    for (int i = 1; i < cnt; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    if (cnt) worker(&jobs[0]);
    for (int i = 1; i < cnt; i++) pthread_join(th[i], NULL);
    Py_END_ALLOW_THREADS
    PyObject *lst = PyList_New(cnt);
    for (int i = 0; i < cnt; i++) {
        if (jobs[i].err) { PyErr_SetString(PyExc_RuntimeError, "openssl fail"); Py_DECREF(lst); Py_DECREF(out); return NULL; }
        PyList_SET_ITEM(lst, i, Py_BuildValue("(y#y#n)", jobs[i].t1, (Py_ssize_t)16, jobs[i].t2, (Py_ssize_t)16, (Py_ssize_t)((jobs[i].len + 15) / 16)));
    }
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&rk);
    return Py_BuildValue("(NN)", out, lst);
}

static PyMethodDef M[] = {{"enc", enc, METH_VARARGS, ""}, {NULL}};
static struct PyModuleDef D = {PyModuleDef_HEAD_INIT, "_cc", NULL, -1, M};
PyMODINIT_FUNC PyInit__cc(void) {
    g_mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    g_ciph = EVP_CIPHER_fetch(NULL, "ChaCha20", NULL);
    if (!g_mac || !g_ciph) { PyErr_SetString(PyExc_ImportError, "openssl fetch"); return NULL; }
    return PyModule_Create(&D);
}
